const defaults={quality:'balanced',exposure:1,hud:'compact',vignette:true};const valid={performance:{dpr:.85,fps:30},balanced:{dpr:1.2,fps:60},cinematic:{dpr:1.6,fps:60}};let saved={};try{saved=JSON.parse(globalThis.localStorage?.getItem('metro-visual105')||'{}');}catch{}let state={...defaults,...saved};if(!valid[state.quality])state.quality='balanced';state.exposure=Math.min(1.2,Math.max(.75,Number(state.exposure)||1));state.hud=state.hud==='extended'?'extended':'compact';let revision=0;const subscribers=new Set();
export const visualState105=()=>({...state,profile:valid[state.quality],revision});
export function setVisual105(patch){const next={...state,...patch};if(!valid[next.quality])throw Error('Calidad no disponible');next.exposure=Math.min(1.2,Math.max(.75,Number(next.exposure)||1));next.hud=next.hud==='extended'?'extended':'compact';next.vignette=Boolean(next.vignette);state=next;revision++;try{globalThis.localStorage?.setItem('metro-visual105',JSON.stringify(state));}catch{}for(const cb of subscribers)cb(visualState105());return visualState105();}
export function watchVisual105(cb){subscribers.add(cb);return()=>subscribers.delete(cb);}
